get isInDST() {
  if (this.isOffsetFixed) {
    return false;
  } else {
    // DST is in effect when the offset is greater than the smallest offset the zone
    // uses during the year, i.e. its standard-time offset. Comparing against a fixed
    // pair of months (e.g. January and May) is wrong for years in which DST covers
    // those months, such as the US in 1974, when DST ran from January 6th to October 27th.
    let standardOffset = this.offset;
    for (let month = 1; month <= 12; month++) {
      const offset = this.set({ month }).offset;
      if (offset < standardOffset) {
        standardOffset = offset;
      }
    }
    return this.offset > standardOffset;
  }
}

